Record TrbSyms (B : asyms) : Prop := {
ts_inst : as_inst B = TRB_INST;
ts_tp : as_tp B = TRB_TP;
ts_tsd : as_tsd B = TRB_TSD;
ts_gp : as_gp B = TRB_GP;
ts_code : as_code B = Trb_code;
ts_errno : as_errno B = TRB_ERRNO;
ts_depot : as_depot B = TRB_DEPOT;
ts_store : as_store B = TRB_STORE;
ts_ial_lo : as_ialloc_lo B = TRB_IAL_LO;
ts_ial_hi : as_ialloc_hi B = TRB_IAL_HI;
ts_ial_w : as_ialloc_w B = TRB_IAL_W;
ts_ial_flag : as_ialloc_flag B = TRB_IAL_FLAG;
ts_oom : as_oom_byte B = TRB_OOM;
ts_ok : asyms_ok B;
ts_owned : as_owned_static B = Trb_owned_static;
ts_const : forall ly, as_const B ly = Trb_const ly;
ts_junk : forall ly r, In r (as_junk B ly) -> exists z, fst r = ANum z /\ 0xa2000 <= z /\ z + snd r <= 0x600000;
ts_junk_comb : forall ly, In (ANum (TRB_INST + o_comb_stats), 40) (as_junk B ly);
ts_junk_ly : forall ly ly', as_junk B ly' = as_junk B ly;
ts_zsh : as_zero_shadow B = Trb_zero_shadow;
ts_universe : universe_ok (as_universe B);
ts_universe_drv : forall t, In t DRV_TRACES -> In t (as_universe B);
ts_hash : forall h, (h < 2)%nat -> (as_dhash B (TRB_TR0 h)) mod 2 ^ 64 = TRB_HASH h
}.
